1	// Guide content for page 3, drawn with the page's own marks (pins, link arcs, ladder marks). Rendered inside the
2	// shared Dock (components/Guide.tsx) through its `guide` slot; reuses the dock's guide.css classes.
3	import type { Requirement } from "@/lib/definition";
4	import { DOMAIN_COLOR, domainColor } from "./data";
5	
6	type MarkKind = "held" | "new" | "changed" | "weakened" | "domains" | "synergy" | "enables" | "conflicts"
7	  | "cited" | "projected" | "assumption" | "gap" | "pm" | "ai";
8	const INK = "#f2f4f7", AMBER = "#f5a524", BLUE = "#4d94ff";
9	const C = DOMAIN_COLOR.interior;
10	
11	function Mark({ kind }: { kind: MarkKind }) {
12	  const s = { width: 18, height: 18, viewBox: "0 0 18 18", "aria-hidden": true, className: "gmark" } as const;
13	  switch (kind) {
14	    case "held": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill={C} /></svg>;
15	    case "new": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill="none" stroke={C} strokeWidth="1.6" /></svg>;
16	    case "changed": return <svg {...s}><circle cx="9" cy="9" r="6" fill="none" stroke={C} strokeWidth="1.3" /><circle cx="9" cy="9" r="2.8" fill={C} /></svg>;
17	    case "weakened": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill={AMBER} /><path d="M6.5 6.5l5 5M11.5 6.5l-5 5" stroke="#000" strokeWidth="1.3" /></svg>;
18	    case "domains": return <svg {...s}>{Object.values(DOMAIN_COLOR).slice(0, 6).map((c, i) => <circle key={c} cx={3 + (i % 3) * 6} cy={i < 3 ? 6 : 12} r="2.2" fill={c} />)}</svg>;
19	    case "synergy": return <svg {...s}><path d="M2 15Q9 0 16 15" fill="none" stroke={INK} strokeWidth="1.4" /></svg>;
20	    case "enables": return <svg {...s}><path d="M2 15Q9 0 16 15" fill="none" stroke={INK} strokeWidth="1.4" /><path d="M16.5 15.5l-1-5-3.5 3.2z" fill={INK} /></svg>;
21	    case "conflicts": return <svg {...s}><path d="M2 15Q9 0 16 15" fill="none" stroke={INK} strokeWidth="1.4" strokeDasharray="2.2 2" /></svg>;
22	    case "cited": return <svg {...s}><circle cx="9" cy="9" r="4" fill={INK} /></svg>;
23	    case "projected": return <svg {...s}><circle cx="9" cy="9" r="4" fill="none" stroke={INK} strokeWidth="1.5" /></svg>;
24	    case "assumption": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill="none" stroke={INK} strokeWidth="1.3" strokeDasharray="2 1.8" /></svg>;
25	    case "gap": return <svg {...s}><text x="9" y="13" textAnchor="middle" fontSize="11" fontWeight="600" fill={INK}>?</text></svg>;
26	    case "pm": return <svg {...s}><circle cx="9" cy="9" r="7" fill="rgba(28,105,212,0.25)" /><circle cx="9" cy="9" r="4" fill={BLUE} /></svg>;
27	    case "ai": return <svg {...s}><rect x="2.5" y="4.5" width="13" height="9" rx="2" fill="none" stroke="#868d99" /><text x="9" y="11.5" textAnchor="middle" fontSize="6.5" fontWeight="600" fill="#b4bac4">AI</text></svg>;
28	  }
29	}
30	
31	interface Row { mark: MarkKind; name: string; text: string }
32	interface Page { title: string; lead?: string; rows?: Row[]; uses?: string; notes?: string[] }
33	
34	const PAGE: Page = {
35	  title: "Definition",
36	  lead: "Each requirement gets one measurable target, defined on today's car. Pins sit where the customer feels it; arcs show which requirements pull on the same resource.",
37	  rows: [
38	    { mark: "domains", name: "Pin colour", text: "The vehicle domain: exterior, interior, powertrain, chassis, assistance, digital, variants." },
39	    { mark: "held", name: "Held", text: "Defined at the earlier checkpoint, target unchanged." },
40	    { mark: "new", name: "New", text: "Defined at this checkpoint." },
41	    { mark: "changed", name: "Target moved", text: "The recommended target changed since the earlier checkpoint." },
42	    { mark: "weakened", name: "Weakened", text: "Less evidence than before." },
43	    { mark: "synergy", name: "Synergy", text: "Solid arc: working on one helps the other. Thicker = stronger." },
44	    { mark: "enables", name: "Enables", text: "Solid arc with a cone: one makes the other possible." },
45	    { mark: "conflicts", name: "Conflicts / competes", text: "Dashed arc: they pull on the same resource, named at the top of the arc (mass, energy, thermal …)." },
46	    { mark: "cited", name: "Cited number", text: "Backed by a source; click its id to see it." },
47	    { mark: "projected", name: "Projected", text: "Extrapolated from a named trend." },
48	    { mark: "assumption", name: "Assumption", text: "No evidence; the reasoning is given." },
49	    { mark: "gap", name: "Gap", text: "No data. Never filled with an invented number; it becomes a research task." },
50	    { mark: "ai", name: "AI", text: "The rung the AI recommends." },
51	    { mark: "pm", name: "PM", text: "The rung the PM chose, with a rationale." },
52	  ],
53	  notes: ["Click a pin or a list row to open it; the camera flies to its zone.", "Switch the car line and filter domains top-left.", "← → change the checkpoint; new pins and links pulse once."],
54	};
55	
56	function forRequirement(r: Requirement): Page {
57	  return {
58	    title: "Requirement definition",
59	    lead: "One customer requirement with one primary metric, its acceptance criteria and a target ladder per car line and market.",
60	    uses: "The AI drafts the metric and ladder from the area's evidence and benchmarks, and recommends a rung. The PM chooses the rung with a rationale; the AI never decides. Linked requirements are proposals the PM confirms or removes.",
61	    rows: [
62	      { mark: "cited", name: "Ladder", text: "Today → threshold → target → stretch on one scale, better to the right." },
63	      { mark: "conflicts", name: "Links", text: `${r.title} draws on ${r.aspects.length ? "the same resources as the linked requirements below" : "shared resources"}.` },
64	    ],
65	    notes: ["Choosing a rung asks for a rationale; it goes into the audit trail.", "Gaps list the numbers still missing."],
66	  };
67	}
68	
69	export function DefinitionGuide({ sel }: { sel: Requirement | null }) {
70	  const page = sel ? forRequirement(sel) : PAGE;
71	  return (
72	    <div className="guide">
73	      <p className="guide-title">{sel && <i className="dguide-dot" style={{ background: domainColor(sel.domain) }} aria-hidden />}{page.title}</p>
74	      {page.lead && <p className="guide-lead">{page.lead}</p>}
75	      {page.uses && <div className="guide-uses"><span className="label">How the AI uses it</span><p>{page.uses}</p></div>}
76	      {page.rows && (
77	        <ul className="guide-rows">
78	          {page.rows.map((r) => <li key={r.name}><Mark kind={r.mark} /><span><b>{r.name}</b> {r.text}</span></li>)}
79	        </ul>
80	      )}
81	      {page.notes && <ul className="guide-notes">{page.notes.map((n) => <li key={n}>{n}</li>)}</ul>}
82	    </div>
83	  );
84	}
