// API shapes for the requirement-definition layer (D-048, api/routers/definition.py; contract in
// foundation/documents/requirement-definition.md → "API").
import type { CheckpointId, TrackState } from "./types";
import type { Orientation, ZoneDef } from "@/three/frame";

export type LineName = "1 Series" | "5 Series" | "7 Series";
export type Basis = "cited" | "projected" | "assumption" | "gap";
export type Rung = "baseline" | "threshold" | "target" | "stretch";
export type ChoosableRung = Exclude<Rung, "baseline">;
export type Relation = "conflicts" | "competes_for" | "enables" | "synergy";
export type Via = "energy" | "mass" | "thermal" | "package" | "attention" | "aero" | "acoustic" | "compute";
/** Track state of a requirement / link; the spec track reports a moved recommended target as "changed". */
export type DefState = TrackState | "changed";

export interface Level {
  value: number | null;
  text: string;
  basis: Basis;
  source_ids: string[];
  note: string;
}

export interface Choice { level: ChoosableRung; rationale: string; actor: string; at: string }

export interface LadderRow {
  line: LineName | string;
  market: string;
  baseline: Level | null;
  threshold: Level;
  target: Level;
  stretch: Level | null;
  recommended: ChoosableRung;
  rationale: string;
  choice?: Choice | null;
}

export interface Metric {
  name: string;
  unit: string;
  direction: "higher" | "lower" | "binary";
  method?: string | null;
  conditions?: string | null;
}

export interface Acceptance { criterion: string; condition: string; pass: string }

export interface Requirement {
  key: string;
  version: number;
  area_key: string;
  area_title: string;
  title: string;
  statement: string;
  domain: string;
  aspects: string[];
  zones: string[];
  lines: string[];
  markets: string[];
  decision_type: string | null;
  today_status: string | null;
  horizon: string | null;
  horizon_year: number | null;
  kano: string | null;
  state: DefState | null;
  change_note: string | null;
  metric: Metric | null;
  acceptance: Acceptance[];
  ladder: LadderRow[];
  gaps: string[];
  assumptions: string[];
  evidence_count: number;
}

export interface LinkReview { verdict: "confirmed" | "removed" | "added"; actor: string; rationale: string; at: string }

export interface DefLink {
  id: string | number;
  a: string;
  b: string;
  relation: Relation;
  via: Via | string;
  strength: 1 | 2 | 3 | number;
  direction: "a_to_b" | "b_to_a" | "mutual";
  rationale: string;
  state: DefState | null;
  review: LinkReview | null;
}

export interface Bundle { id: string; keys: string[]; reason: string }

export interface RunInfo { id: number; finished_at: string | null; stats: Record<string, unknown> }

export interface ModelInfo { url: string | null; orientation: Orientation; attribution?: string | null; stand_in?: string | null }

export interface DefinitionPayload {
  checkpoint: CheckpointId;
  ready: boolean;
  runs: { define: RunInfo | null; specify: RunInfo | null; couple: RunInfo | null };
  domains: { key: string; label: string; aspects: string[] }[];
  resources: Record<string, string>;
  zones: Record<string, ZoneDef>;
  models: Record<string, ModelInfo>;
  requirements: Requirement[];
  links: DefLink[];
  bundles: Bundle[];
}

export interface EvidenceRef {
  id: string | number;
  kind: string;
  text: string;
  url: string | null;
  tier: string | null;
  published: string | null;
  relation: string | null;
  quote: string | null;
}

export interface RequirementDetail extends Requirement {
  evidence: EvidenceRef[];
  facts: Record<string, unknown>[];
  area: { key: string; title: string; need: string } | null;
  history: { checkpoint: string; version: number; change_note: string | null }[];
}

export interface ChoiceBody { key: string; line: string; market: string; level: ChoosableRung; rationale: string; actor: string }
export interface LinkReviewBody {
  a: string; b: string; relation: Relation; verdict: LinkReview["verdict"]; via?: string; strength?: number; rationale: string; actor: string;
}
// Page-3 view state, shared by the HUD (DOM) and the definition layer inside the canvas without threading props
// through Scan/Scene. A tiny external store read with useSyncExternalStore.
import { useSyncExternalStore } from "react";
import type { ChoosableRung, LineName } from "@/lib/definition";
import type { DefStage } from "./stages";

export type LinkMode = "strong" | "all" | "off";

export interface DefView {
  selected: string | null;        // requirement key
  hover: string | null;           // requirement key under the pointer (pin or list row)
  hoverPos: { x: number; y: number } | null;
  line: LineName;
  domains: string[];              // empty = all
  links: LinkMode;
  bundle: string | null;          // highlighted bundle id
  /** optimistic PM choices, key `${req}|${line}|${market}` → rung (cleared when the server state arrives) */
  pending: Record<string, ChoosableRung>;
  /** optimistic link reviews, link id → verdict */
  pendingLinks: Record<string, "confirmed" | "removed">;
  /** the definition stage in view (stages.ts); set by the funnel, read by the 3D stage layer */
  stage: DefStage;
  /** true while the arrival play steps through the stages on its own */
  auto: boolean;
  /** area diamond / domain group under the pointer (lights up their requirements) */
  hoverArea: string | null;
  hoverDomain: string | null;
}

const LINE_KEY = "definition.line";
const readLine = (): LineName => {
  try { const v = localStorage.getItem(LINE_KEY); return v === "1 Series" || v === "7 Series" ? v : "5 Series"; } catch { return "5 Series"; }
};

let state: DefView = {
  selected: null, hover: null, hoverPos: null, line: readLine(), domains: [], links: "strong", bundle: null, pending: {}, pendingLinks: {},
  stage: "areas", auto: false, hoverArea: null, hoverDomain: null,
};
const subs = new Set<() => void>();

export function setView(patch: Partial<DefView> | ((s: DefView) => Partial<DefView>)) {
  const p = typeof patch === "function" ? patch(state) : patch;
  state = { ...state, ...p };
  if (p.line) { try { localStorage.setItem(LINE_KEY, p.line); } catch { /* private mode */ } }
  subs.forEach((f) => f());
}
export const getView = () => state;
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

export function useView<T>(pick: (s: DefView) => T): T {
  return useSyncExternalStore(subscribe, () => pick(state));
}

export const select = (key: string | null) => setView({ selected: key, hover: null, hoverPos: null });
// Stepping through the definition layer on page 3 (frontend only: every stage's output is already in /api/definition).
// areas: the requirement-area diamonds rise from their Structure ring to a plane above the volume, which sinks away.
// drafted: each diamond splits into its requirements, which settle into one group per vehicle domain.
// specified: each requirement shows its recommended target; a "?" marks open gaps.
// linked: the couplings between requirements appear as arcs between the groups.
// car: today's car rises and every requirement flies to its zone on it.
import type { DefData } from "./data";

export const DEF_STAGES = ["areas", "drafted", "specified", "linked", "car"] as const;
export type DefStage = (typeof DEF_STAGES)[number];
export const DEF_STAGE_LABEL: Record<DefStage, string> = {
  areas: "Areas", drafted: "Drafted", specified: "Specified", linked: "Linked", car: "On the car",
};

export const defAtLeast = (s: DefStage, t: DefStage) => DEF_STAGES.indexOf(s) >= DEF_STAGES.indexOf(t);

/** Stages whose output this checkpoint has, in order. Areas need Structure; the rest need drafted requirements. */
export function defDoneStages(def: DefData, structureReady: boolean): DefStage[] {
  const d = def.data;
  const has = d.requirements.length > 0;
  return DEF_STAGES.filter((s) => {
    if (s === "areas") return structureReady;
    if (!has) return false;
    if (s === "specified") return def.sample || !!d.runs.specify || d.requirements.some((r) => r.ladder.length > 0);
    if (s === "linked") return def.sample || !!d.runs.couple || d.links.length > 0;
    return true;
  });
}
