149:.ladder-name { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.02em; }
150:.ladder-tags { display: inline-flex; gap: 3px; }
151:.ladder-ai, .ladder-pm { font-size: 9.5px; font-weight: 600; letter-spacing: 0.08em; line-height: 13px; padding: 0 3px; border-radius: 3px; color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--hair-2); }
152:.ladder-pm { color: var(--sweep-hi); box-shadow: inset 0 0 0 1px rgba(77, 148, 255, 0.6); }
153:.ladder-mark { width: 11px; height: 11px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 11px; font-weight: 600; line-height: 1; color: var(--ink); background: var(--void); }
154:.ladder-mark[data-basis="cited"] { background: var(--ink); }
155:.ladder-mark[data-basis="projected"] { box-shadow: inset 0 0 0 1.5px var(--ink); }
156:.ladder-mark[data-basis="assumption"] { border: 1.3px dashed var(--ink); }
157:.ladder-mark[data-basis="gap"] { width: 14px; height: 14px; color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--hair-2); }
158:.ladder-mark.sm { width: 9px; height: 9px; font-size: 9px; }
159:.ladder-mark.sm[data-basis="gap"] { width: 11px; height: 11px; }
