164:.ladder-rung[data-on] .ladder-mark { background: var(--sweep-hi); border-color: var(--sweep-hi); box-shadow: 0 0 0 4px var(--sweep-wash); color: var(--void); }
165:.ladder-rung[data-picking] .ladder-mark { outline: 1px solid var(--ink); outline-offset: 3px; }
166:.ladder-basis { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
167:.ladder-basis li { display: grid; grid-template-columns: 11px 62px 1fr; align-items: baseline; gap: 8px; font-size: var(--t-label); color: var(--ink-3); line-height: 1.45; }
168:.ladder-basis .ladder-mark { align-self: center; }
